// RaftSnapshot wraps RaftSnapshotWithContext using context.Background.
func (c *Sys) RaftSnapshot(snapWriter io.Writer) error {
	return c.RaftSnapshotWithContext(context.Background(), snapWriter)
}

// RaftSnapshotWithContext invokes the API that takes the snapshot of the raft cluster and
// writes it to the supplied io.Writer.
func (c *Sys) RaftSnapshotWithContext(ctx context.Context, snapWriter io.Writer) error {
	r := c.c.NewRequest(http.MethodGet, "/v1/sys/storage/raft/snapshot")
	r.URL.RawQuery = r.Params.Encode()

	resp, err := c.c.httpRequestWithContext(ctx, r)
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	// Make sure that the last file in the archive, SHA256SUMS.sealed, is present
	// and non-empty.  This is to catch cases where the snapshot failed midstream,
	// e.g. due to a problem with the seal that prevented encryption of that file.
	var wg sync.WaitGroup
	wg.Add(1)
	var verified bool

	rPipe, wPipe := io.Pipe()
	dup := io.TeeReader(resp.Body, wPipe)
	go func() {
		defer func() {
			io.Copy(io.Discard, rPipe)
			rPipe.Close()
			wg.Done()
		}()

		uncompressed, err := gzip.NewReader(rPipe)
		if err != nil {
			return
		}

		t := tar.NewReader(uncompressed)
		var h *tar.Header
		for {
			h, err = t.Next()
			if err != nil {
				return
			}
			if h.Name != "SHA256SUMS.sealed" {
				continue
			}
			var b []byte
			b, err = io.ReadAll(t)
			if err != nil || len(b) == 0 {
				return
			}
			verified = true
			return
		}
	}()

	// Copy bytes from dup to snapWriter.  This will have a side effect that
	// everything read from dup will be written to wPipe.
	_, err = io.Copy(snapWriter, dup)
	wPipe.Close()
	if err != nil {
		rPipe.CloseWithError(err)
		return err
	}
	wg.Wait()

	if !verified {
		return ErrIncompleteSnapshot
	}
	return nil
}

// RaftSnapshotRestore wraps RaftSnapshotRestoreWithContext using context.Background.
func (c *Sys) RaftSnapshotRestore(snapReader io.Reader, force bool) error {
	return c.RaftSnapshotRestoreWithContext(context.Background(), snapReader, force)
}

// RaftSnapshotRestoreWithContext reads the snapshot from the io.Reader and installs that
// snapshot, returning the cluster to the state defined by it.
func (c *Sys) RaftSnapshotRestoreWithContext(ctx context.Context, snapReader io.Reader, force bool) error {
	path := "/v1/sys/storage/raft/snapshot"
	if force {
		path = "/v1/sys/storage/raft/snapshot-force"
	}

	r := c.c.NewRequest(http.MethodPost, path)
	r.Body = io.NopCloser(snapReader)

	resp, err := c.c.httpRequestWithContext(ctx, r)
	if err != nil {
		return err
	}
	defer resp.Body.Close() //nolint:errcheck

	return nil

// ResetJSONBody is used to reset the body for a redirect
func (r *Request) ResetJSONBody() error {
	if r.BodyBytes == nil {
		return nil
	}
	return r.SetJSONBody(r.Obj)
}

// DEPRECATED: ToHTTP turns this request into a valid *http.Request for use
// with the net/http package.
func (r *Request) ToHTTP() (*http.Request, error) {
	req, err := r.toRetryableHTTP()
	if err != nil {
		return nil, err
	}

	switch {
	case r.BodyBytes == nil && r.Body == nil:
		// No body

	case r.BodyBytes != nil:
		req.Body = io.NopCloser(bytes.NewReader(r.BodyBytes))

	default:
		if c, ok := r.Body.(io.ReadCloser); ok {
			req.Body = c
		} else {
			req.Body = io.NopCloser(r.Body)
		}
	}

pub(crate) fn begin_native_snapshot_before(
    &mut self,
    mut request: ServiceRequest<'_>,
    deadline: Instant,
) -> NativeSnapshotAdmission {
    let _scope = crate::request_deadline::RequestDeadlineScope::enter(deadline);
    if crate::request_deadline::current().is_none_or(|limit| Instant::now() >= limit) {
        erase_json(&mut request.body);
        return NativeSnapshotAdmission::Execute(RequestExecution::Complete(Response::error(
            503,
            "snapshot admission deadline exceeded",
        )));
    }
    let accepted = matches!(
        request.path,
        "sys/storage/raft/snapshot" | "sys/storage/raft/snapshot-force" | NATIVE_HA_REPAIR_PATH
    );
    #[cfg(feature = "native-v6-storage")]
    let accepted = accepted
        || (request.path == crate::engines::kv2_lossless_export::PATH
            && matches!(request.method, "GET" | "HEAD"));
    if !accepted {
        erase_json(&mut request.body);
        return NativeSnapshotAdmission::Execute(RequestExecution::Complete(Response::error(
            400,
            "invalid native snapshot route",
        )));
    }
    // This is before authentication/finite-use persistence, staging and
    // JSON HA forwarding. The receiving leader independently authorizes
    // the original request; observing a leader never grants authority.
    match self.configured_standby_destination() {
        Ok(Some(origin)) => {
            let now = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap_or(Duration::ZERO)
                .as_secs();
            let fingerprint = self.request_fingerprint(
                request.method,
                request.path,
                request.namespace,
                request.token,
            );
            erase_json(&mut request.body);
            if self
                .audit_event("request", &fingerprint, now, None)
                .is_err()
            {
                return NativeSnapshotAdmission::Execute(RequestExecution::Complete(
                    Response::error(503, "snapshot redirect audit unavailable"),
                ));
            }
            if self
                .audit_event("response", &fingerprint, now, Some(307))
                .is_err()
            {
                crate::service::openbao_wrapper::fence(&self.openbao_wrapper_owner);
                self.recovery_required = true;
                self.ha_activation = None;
                return NativeSnapshotAdmission::Execute(RequestExecution::Complete(
                    Response::error(503, "snapshot redirect response audit unavailable"),
                ));
            }
            return NativeSnapshotAdmission::Redirect(origin);
        }
        Err(response) => {
            erase_json(&mut request.body);
            return NativeSnapshotAdmission::Execute(RequestExecution::Complete(response));
        }
        Ok(None) => {}
    }
    // Pair wall time and the monotonic anchor before reconciliation, audit,
    // authentication and finite-use persistence can spend admission time.
    let started = Instant::now();
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or(Duration::ZERO);
    let previous_clock = self.native_snapshot_clock.replace((started, now));
    let previous = self.native_snapshot_transport;
    self.native_snapshot_transport = true;
    let result = self.begin_request_before(request, deadline, false);
    self.native_snapshot_transport = previous;
    self.native_snapshot_clock = previous_clock;
    NativeSnapshotAdmission::Execute(result)
}

pub(super) fn configured_standby_destination(
    &self,
) -> Result<Option<TrustedSnapshotOrigin>, Response> {
    let Some(process) = self.ha.as_ref() else {
        return Ok(None);
    };
    if self.state.is_none() {
        return Err(Response::error(503, "server is sealed"));
    }
    let process = process
        .lock_for_request()
        .map_err(|_| Response::error(503, "HA process lock is unavailable"))?;
    let observation = process
        .leader_status()
        .map_err(|_| Response::error(503, "HA leader state is unavailable"))?;
    let leader = observation
        .leader
        .ok_or_else(|| Response::error(503, "HA cluster has no elected leader"))?;
    if leader == observation.local_id {
        return Ok(None);
    }
    process
        .api_address(leader)
        .map(|origin| Some(TrustedSnapshotOrigin(origin.to_owned())))
        .ok_or_else(|| Response::error(503, "HA leader API address is unavailable"))
}

