/// A closed request-side transport selection, never a raw-response authority.

fn encode<T: Serialize>(magic: &[u8; 5], value: &T) -> Result<Vec<u8>, String> {
    let json =
        Zeroizing::new(serde_json::to_vec(value).map_err(|_| "cannot encode HA forward frame")?);
    if json.len() > MAX_FORWARD_FRAME_BYTES - 9 {
        return Err("HA forward frame exceeds transport bound".into());
    }
    let length = u32::try_from(json.len()).map_err(|_| "HA forward frame is oversized")?;
    let mut encoded = Vec::with_capacity(9 + json.len());
    encoded.extend_from_slice(magic);
    encoded.extend_from_slice(&length.to_be_bytes());
    encoded.extend_from_slice(&json);
    Ok(encoded)

fn decode<T: for<'de> Deserialize<'de>>(magic: &[u8; 5], encoded: &[u8]) -> Result<T, String> {
    if encoded.len() < 9 || encoded.len() > MAX_FORWARD_FRAME_BYTES || &encoded[..5] != magic {
        return Err("HA forward frame is invalid".into());
    }
    let length = u32::from_be_bytes(
        encoded[5..9]
            .try_into()
            .map_err(|_| "HA forward frame length is invalid")?,
    ) as usize;
    if encoded.len() != 9 + length {
        return Err("HA forward frame length does not match payload".into());
    }
    serde_json::from_slice(&encoded[9..]).map_err(|_| "HA forward frame JSON is invalid".into())

// Only HaProcess's authenticated exchange can construct this type. No Clone:
// the exact completion travels once to the follower's terminal audit gate.
pub(crate) struct CompletedForwardReceipt {
    wire: CompletionWire,
    pub cluster: String,
    pub source: u64,
    pub target: u64,
    pub deadline: Instant,
}
impl CompletedForwardReceipt {
    pub(super) fn verified(
        wire: CompletionWire,
        exchange: CompletedExchange<'_>,
    ) -> Result<Self, String> {
        let CompletedExchange {
            cluster,
            source,
            target,
            deadline,
            nonce,
            request,
            response_digest,
        } = exchange;
        if Instant::now() >= deadline
            || wire.nonce != nonce
            || wire.request_digest != digest(request)
            || wire.response_digest != response_digest
            || wire.audit_sequence == 0
            || wire.audit_mac == [0; 32]
            || wire.identity.digest() == [0; 32]
            || wire.applied_index == 0
            || !wire.prefix.valid()
            || wire.applied_index != wire.prefix.index()
            || wire.owner_projection == [0; 32]
            || wire.publication_mac == [0; 32]
            || (wire.precise && wire.floor.is_none())
            || (wire.oidc_missing_session_denial.is_some() && wire.actor.is_some())
            || wire
                .oidc_missing_session_denial
                .as_ref()
                .is_some_and(|denial| denial.non_auth_owner_projection == [0; 32])
        {
            return Err("HA completed-forward proof is invalid".into());
        }
        #[cfg(feature = "native-v6-storage")]
        if let Some(read) = wire.native_data_read.as_ref() {
            let ingress = NativeDataReadIngress::capture(request)
                .ok_or("native completed read ingress absent")?;
            if wire.oidc_missing_session_denial.is_some()
                || wire.acknowledgement_only
                || wire.actor.is_none()
                || !read.data.structurally_valid()
                || read.stable_owner_projection == [0; 32]
                || !read.data.matches_ingress(&ingress.namespace, &ingress.path)
            {
                return Err("native completed read proof scope is invalid".into());
            }
        }
        Ok(Self {
            wire,
            cluster,
            source,
            target,
            deadline,
        })
    }
