    // interpreting its log prefix against a later local quorum witness.
    #[cfg(test)]

pub(crate) fn response_digest(response: &crate::Response) -> Result<[u8; 32], String> {
    // Ordinary completion digests remain byte-identical to the old version.
    // A negotiated unwrap origin is additionally bound to the same completion.
    let encoded = zeroize::Zeroizing::new(
        if let Some(stored) = response
            .unwrapped_json
            .as_ref()
            .and_then(|origin| origin.stored_reply())
        {
            serde_json::to_vec(&(
                response.status,
                &response.body,
                &response.response_headers,
                crate::ha_forward::UnwrapFramingWire::StoredJson,
                stored,
            ))
        } else if let Some(origin) = &response.unwrapped_json {
            let framing = origin
                .framing_wire(&response.body)
                .map_err(|_| "HA private response origin differs")?;
            serde_json::to_vec(&(
                response.status,
                &response.body,
                &response.response_headers,
                framing,
            ))
        } else {
            serde_json::to_vec(&(response.status, &response.body, &response.response_headers))
        }
        .map_err(|_| "HA response digest is unavailable")?,
    );
    Ok(digest(&encoded))

pub(crate) struct CompletionScope {
    previous: Option<Capture>,
}
impl CompletionScope {
    pub(crate) fn enter(
        nonce: Option<[u8; 32]>,
        request: &[u8],
        deadline: Instant,
        cluster: &str,
        target: u64,
        acknowledgement_route: bool,
    ) -> Self {
        let previous = CAPTURE.with(|slot| {
            slot.replace(nonce.map(|nonce| Capture {
                cluster: cluster.to_owned(),
                target,
                nonce,
                request_digest: digest(request),
                deadline,
                clock: None,
                audited: false,
                actor: None,
                acknowledgement_only: acknowledgement_route,
                diagnostic_step_down: false,
                oidc_missing_session_denial: None,
                quota_response_headers: None,
                #[cfg(feature = "native-v6-storage")]
                native_data_read: None,
                #[cfg(feature = "native-v6-storage")]
                native_data_read_ingress: NativeDataReadIngress::capture(request),
                complete: None,
            }))
        });
        Self { previous }
    }
    #[cfg(feature = "native-v6-storage")]
    pub(crate) fn has_native_data_read() -> bool {
        CAPTURE.with(|slot| {
            slot.borrow()
                .as_ref()
                .is_some_and(|c| c.native_data_read.is_some())
        })
    }
    pub(crate) fn has_oidc_missing_session_denial() -> bool {
        CAPTURE.with(|slot| {
            slot.borrow()
                .as_ref()
                .is_some_and(|c| c.oidc_missing_session_denial.is_some())
        })
    }
    pub(crate) fn active() -> bool {
        CAPTURE.with(|slot| slot.borrow().is_some())
    }
    pub(crate) fn deadline() -> Option<Instant> {
        CAPTURE.with(|slot| slot.borrow().as_ref().map(|c| c.deadline))
    }
    pub(crate) fn matches_owner(cluster: &str, local: u64) -> bool {
        CAPTURE.with(|slot| {
            slot.borrow()
                .as_ref()
                .is_some_and(|c| c.cluster == cluster && c.target == local)
        })
    }
    pub(crate) fn finish(&self) -> Option<CompletionWire> {
        CAPTURE.with(|slot| slot.borrow_mut().as_mut().and_then(|c| c.complete.take()))
    }
}
impl Drop for CompletionScope {
    fn drop(&mut self) {
        CAPTURE.with(|slot| {
            slot.replace(self.previous.take());
        });
    }

pub(crate) fn seal(response: &crate::Response, publication: CompletedPublication<'_>) {
    let CompletedPublication {
        proof_key,
        identity,
        prefix,
        owner_projection,
        floor,
        precise,
        audit_sequence,
        audit_mac,
        non_auth_owner_projection,
    } = publication;
    let applied_index = prefix.index();
    CAPTURE.with(|slot| {
        if let Some(c) = slot.borrow_mut().as_mut() {
            let live_clock = c.clock.is_some_and(|clock| {
                clock.observed_at().is_ok()
                    && (!precise || floor.is_some_and(|at| at >= clock.admitted_at()))
            });
            if !c.audited || !live_clock || Instant::now() >= c.deadline {
                return;
            }
            let Ok(response_digest) = response_digest(response) else {
                return;
            };
            let quota_original = c
                .quota_response_headers
                .as_ref()
                .filter(|headers| headers.completed == response_digest)
                .map(|headers| headers.original);
            let logical_headers_empty =
                response.response_headers.is_empty() || quota_original.is_some();
            let no_actor = c.actor.is_none();
            #[cfg(feature = "native-v6-storage")]
            let has_oidc_denial = c.oidc_missing_session_denial.is_some();
            let mut wire = CompletionWire {
                nonce: c.nonce,
                request_digest: c.request_digest,
                response_digest,
                identity,
                floor,
                precise,
                audit_sequence,
                audit_mac,
                applied_index,
                prefix,
                owner_projection,
                publication_mac: [0; 32],
                actor: c.actor.take(),
                oidc_missing_session_denial: c.oidc_missing_session_denial.take().and_then(
                    |(denial, expected)| {
                        ((expected == response_digest || quota_original == Some(expected))
                            && no_actor
                            && non_auth_owner_projection != [0; 32]
                            && logical_headers_empty
                            && response.consistency_index.is_none())
                        .then_some(OidcDenialPublication {
                            denial,
                            non_auth_owner_projection,
                        })
                    },
                ),
                #[cfg(feature = "native-v6-storage")]
                native_data_read: c.native_data_read.take().and_then(|read| {
                    ((read.response == response_digest || quota_original == Some(read.response))
                        && logical_headers_empty
                        && !has_oidc_denial
                        && !c.acknowledgement_only
                        && !no_actor
                        && response.status == 200
                        && response.unwrapped_json.is_none())
                    .then_some(read)
                    .and_then(|read| {
                        read.stable
                            .map(|stable_owner_projection| NativeDataReadPublication {
                                data: read.data,
                                stable_owner_projection,
                            })
                    })
                }),
                acknowledgement_only: c.acknowledgement_only
                    && response.status == 204
                    && response.body.is_null()
                    && logical_headers_empty,
            };
            let Ok(bytes) = publication_bytes(&wire, &c.cluster, c.target) else {
                return;
            };
            wire.publication_mac
                .copy_from_slice(ring::hmac::sign(&publication_key(proof_key), &bytes).as_ref());
            if Instant::now() < c.deadline {
                c.complete = Some(wire);
            }
        }

pub(super) fn stage_forward_delivery(
    &mut self,
    receipt: CompletedForwardReceipt,
    ha: Arc<Mutex<crate::ha::HaProcess>>,
    namespace: &str,
    clock: Option<RequestClock>,
    now: u64,
) -> Result<ForwardDelivery, Response> {
    let _original_deadline =
        crate::request_deadline::RequestDeadlineScope::enter(receipt.deadline);
    // Catch-up still runs under the actual local Service/Seal/barrier
    // owner and its original deadline. A verified historical epoch install
    // legitimately rotates that owner's nonce. Capture delivery custody
    // only after that installation, never by rebadging an earlier capsule.
    // No request, Actor admission or remote effect is executed again.
    let (identity, witness) = self.sync_completed_forward_receipt(&receipt, &ha, "stage")?;
    let state = self.state.as_ref().ok_or_else(unavailable)?;
    let key = self.barrier_key.as_ref().ok_or_else(unavailable)?;
    let result = ForwardDelivery {
        receipt,
        ha,
        unseal_nonce: Zeroizing::new(self.unseal_nonce.clone()),
        barrier_digest: crate::ha_forward_completion::digest(key.as_slice()),
        namespace: Zeroizing::new(namespace.to_owned()),
        namespace_binding: namespace_runtime::DeliveryBinding::capture(state, namespace),
        clock,
        now,
    };
    self.check_forward_delivery_observed(&result, "stage", identity, witness)?;
    Ok(result)

fn sync_completed_forward_receipt(
    &mut self,
    receipt: &CompletedForwardReceipt,
    ha: &Arc<Mutex<crate::ha::HaProcess>>,
    phase: &'static str,
) -> Result<(StateIdentity, ApplicationReadWitness), Response> {
    let _original_deadline =
        crate::request_deadline::RequestDeadlineScope::enter(receipt.deadline);
    if self
        .ha
        .as_ref()
        .is_none_or(|actual| !Arc::ptr_eq(actual, ha))
    {
        return Err(diagnostic_unavailable(phase, "ha_owner"));
    }
    let original_key = self.barrier_key.as_ref().ok_or_else(unavailable)?;
    receipt
        .verify_publication(original_key.as_slice())
        .map_err(|_| diagnostic_unavailable(phase, "publication_mac"))?;
    // Wait and synchronize before the final original Actor observation.
    // A blocking applied-index wait must never follow that observation.
    crate::ha::observe_native_v6_timing(
        phase,
        "delivery_wait_applied",
        Some(receipt.deadline),
        || {
            ha.lock_for_request()
                .map_err(|_| diagnostic_unavailable(phase, "ha_lock"))?
                .wait_forward_applied(receipt)
                .map_err(|_| diagnostic_unavailable(phase, "wait_applied"))
        },
    )?;
    // No deadline or Actor is renewed when an unrelated completion raced
    // the first materialization. The final witness must authenticate this
    // same actual Service graph before any owner or Actor check follows.
    loop {
        crate::ha::observe_native_v6_timing(
            phase,
            "delivery_local_sync",
            Some(receipt.deadline),
            || self.sync_forward_delivery_before(receipt.deadline),
        )
        .inspect_err(|error| {
            eprintln!(
                "heptabao-forward-diagnostic: phase={phase} guard=sync status={}",
                error.status
            );
        })?;
        let local_identity = self.current_state_identity()?;
        let (identity, witness) = crate::ha::observe_native_v6_timing(
            phase,
            "delivery_fresh_witness",
            Some(receipt.deadline),
            || {
                ha.lock_for_request()
                    .map_err(|_| unavailable())?
                    .application_identity_witness_for_local_root(local_identity)
                    .map_err(|_| diagnostic_unavailable(phase, "fresh_witness"))
            },
        )?;
        if self.current_state_identity()? == identity {
            return Ok((identity, witness));
        }
        if Instant::now() >= receipt.deadline {
            return Err(unavailable());
        }
    }
}

pub(super) fn check_pending_forward_delivery(
    &mut self,
    response: &Response,
) -> Result<(), Response> {
    let Some(pending) = self.pending_forward_delivery.take() else {
        return Err(unavailable());
    };
    let result = match &pending {
        PendingForwardDelivery::Rejected => Err(unavailable()),
        PendingForwardDelivery::Completed(authority) => {
            if authority.receipt.response_matches(response) {
                self.check_forward_delivery(authority, "pre_audit")
            } else {
                Err(diagnostic_unavailable("pre_audit", "response_digest"))
            }
        }
    };
    self.pending_forward_delivery = Some(pending);
    result
}
pub(super) fn complete_forward_delivery(
    &mut self,
    mut response: Response,
    fingerprint: &str,
) -> Response {
    let Some(pending) = self.pending_forward_delivery.take() else {
        return response;
    };
    let PendingForwardDelivery::Completed(authority) = pending else {
        eprintln!("HBHA-MIXED-FWD-R4 phase=pending_exchange_rejected");
        erase_json(&mut response.body);
        response.unwrapped_json = None;
        response.response_headers.clear();
        return unavailable();
    };
    let rejection = if authority.receipt.response_matches(&response) {
        self.check_forward_delivery(&authority, "post_audit").err()
    } else {
        Some(diagnostic_unavailable("post_audit", "response_digest"))
    };
    if let Some(rejection) = rejection {
        erase_json(&mut response.body);
        response.unwrapped_json = None;
        response.response_headers.clear();
        response.consistency_index = None;
        if self
            .audit_event(
                "forward_delivery_veto",
                fingerprint,
                authority.now,
                Some(rejection.status),
            )
            .is_err()
        {
            crate::service::openbao_wrapper::fence(&self.openbao_wrapper_owner);
            self.recovery_required = true;
            self.ha_activation = None;
            return Response::error(
                503,
                "forward delivery veto audit failed; outcome unknown; authoritative recovery required",
            );
        }
        return rejection;
    }

pub(crate) fn seal_forward_completion(&self, response: &Response) {
    if crate::request_deadline::current().is_some_and(|deadline| Instant::now() >= deadline)
        || CompletionScope::deadline().is_none()
        || self.recovery_required
        || self.audit_failed
        || !self.ha_activation_permitted()
    {
        #[cfg(test)]
        eprintln!(
            "HBHA-DIAG-FORWARD-SOURCE-ENTRY deadline_expired={} completion_scope_missing={} recovery_required={} audit_failed={} state_loaded={} barrier_loaded={} durable_loaded={} durable_recovery={}",
            crate::request_deadline::current()
                .is_some_and(|deadline| Instant::now() >= deadline),
            CompletionScope::deadline().is_none(),
            self.recovery_required,
            self.audit_failed,
            self.state.is_some(),
            self.barrier_key.is_some(),
            self.durable.is_some(),
            self.durable
                .as_ref()
                .is_some_and(|durable| durable.recovery_required()),
        );
        seal_diagnostic("entry");
        return;
    }
    let Some(state) = &self.state else {
        seal_diagnostic("state_missing");
        return;
    };
    let Some(ha) = &self.ha else {
        seal_diagnostic("ha_missing");
        return;
    };
    let Ok(ha) = ha.lock_for_request() else {
        seal_diagnostic("ha_lock");
        return;
    };
    let Ok(local) = ha.local_id() else {
        seal_diagnostic("local_id");
        return;
    };
    drop(ha);
    if !CompletionScope::matches_owner(&state.cluster_id, local) {
        seal_diagnostic("scope_owner");
        return;
    }
    let Ok(identity) = self.current_state_identity() else {
        seal_diagnostic("state_identity");
        return;
    };
    let Ok((observed_identity, witness)) = self
        .ha
        .as_ref()
        .ok_or(())
        .and_then(|ha| ha.lock_for_request().map_err(|_| ()))
        .and_then(|ha| {
            ha.application_identity_witness_for_local_root(identity)
                .map_err(|_| ())
        })
    else {
        seal_diagnostic("fresh_witness");
        return;
    };
    if observed_identity != identity {
        seal_diagnostic("witness_identity");
        return;
    }
    let Ok(owner_projection) = self.forward_owner_projection() else {
        seal_diagnostic("projection");
        return;
    };
    if state.namespace_leases.validate().is_err()
        || !crate::ha_forward_completion::original_actor_live(response, |actor, clock| {
            clock.observed_at().is_ok_and(|now| {
                state
                    .auth
                    .validate_forward_actor(actor, AuthorityTime::Precise(now))
                    .is_ok()
            })
        })
    {
        seal_diagnostic("terminal_actor_slots");
        return;
    }
    #[cfg(feature = "native-v6-storage")]
    if CompletionScope::has_native_data_read()
        && let Ok(projection) = self.forward_native_data_read_projection()
    {
        crate::ha_forward_completion::bind_native_data_read_projection(
            projection,
            |data, clock| {
                clock
                    .observed_at()
                    .is_ok_and(|now| state.engines.retained_native_read_visible(data, now))
            },
        );
    }
    crate::ha_forward_completion::seal(
        response,
        crate::ha_forward_completion::CompletedPublication {
            proof_key: match self.barrier_key.as_ref() {
                Some(key) => key.as_slice(),
                None => return,
            },
            identity,
            prefix: witness.completed_prefix(),
            owner_projection,
            floor: state.auth.terminal_token_clock_floor(),
            precise: state.has_token_api_precision_state(),
            audit_sequence: self.audit_sequence,
            audit_mac: self.audit_previous,
            non_auth_owner_projection: if CompletionScope::has_oidc_missing_session_denial() {
                match self.forward_non_auth_owner_projection() {
                    Ok(projection) => projection,
                    Err(_) => {
                        seal_diagnostic("denial_non_auth_projection");
                        return;

    }
    MAX_KV2_JSON_WRITE_BODY
}

const MAX_SNAPSHOT_BODY: usize = 32 * 1024 * 1024;
const MAX_RESPONSE: usize = 32 * 1024 * 1024;

if let Some(ha) = forwarding_ha {
    let forward_timeout = ha
        .lock()
        .map_err(|_| "HA process lock is unavailable".to_owned())?
        .forward_timeout()
        .min(Duration::from_secs(config.timeout_seconds));
    let weak_service = Arc::downgrade(&service);
    let handler: crate::ha::ForwardHandler = Arc::new(move |mut request| {
        let Some(service) = weak_service.upgrade() else {
            return Response::error(503, "HA forward service is unavailable");
        };
        let response = execute_service_request(
            &service,
            ServiceRequest {
                method: &request.method,
                path: &request.path,
                namespace: &request.namespace,
                token: &request.token,
                body: std::mem::take(&mut request.body),
                wrap_ttl_seconds: request.wrap_ttl_seconds,
                origin_peer: request.origin_peer,
                client_certificates: request.client_certificates.take(),
            },
            crate::ha_forward_completion::CompletionScope::deadline().map_or_else(
                || Instant::now() + forward_timeout,
                |original| original.min(Instant::now() + forward_timeout),
            ),
            true,
        );
        request.token.zeroize();
        response
    });
    ha.lock()
        .map_err(|_| "HA process lock is unavailable".to_owned())?
        .register_forward_handler(handler)?;

let is_head = request.method == "HEAD"
    || help::request(&request.method, &request.path, &request.body.0)
        .is_some_and(|(method, _, _)| method == "HEAD");
let native_snapshot = request.native_snapshot.take();
// Index admission precedes logical dispatch and any snapshot body I/O.
// It never authenticates the caller or creates permission to retry.
let consistency = consistency::admit(
    service,
    &request.consistency,
    consistency_settings,
    deadline,
);
let mut service_request = ServiceRequest {
    method: if request.method == "HEAD"
        && request.path != "sys/leader"
        && request.path != "sys/internal/ui/mounts"
        && !request.path.starts_with("sys/internal/ui/mounts/")
        && request.wrap_ttl_seconds.is_none_or(|ttl| ttl == 0)
        && ocsp::query_request("HEAD", &request.path, &request.body.0).is_none()
    {
        "GET"
    } else {
        &request.method
    },
    path: &request.path,
    namespace: &request.namespace,
    token: &request.token,
    body: std::mem::take(&mut request.body.0),
    wrap_ttl_seconds: request.wrap_ttl_seconds,
    origin_peer: Some(peer),
    client_certificates: request.client_certificates.take(),
};
if let Some(target) = request.no_forward_target.take() {
    let data = request.logical_data.get_or_insert_with(Default::default);
    if data
        .bind_local_redirect(
            target,
            (
                service_request.method,
                service_request.path,
                service_request.namespace,
                &service_request.body,
            ),
            attempt_id,
        )
        .is_err()
    {
        crate::service::erase_json(&mut service_request.body);
        return (
            snapshot::NativeReply::Json(Response::error(
                400,
                "invalid original HTTP redirect preference",
            )),
            is_head,
            request.namespace,
        );
    }
}
let _logical_data = match crate::request_metadata::Scope::enter(
    request.logical_data.take(),
    service_request.method,
    service_request.path,
    service_request.namespace,
    &service_request.body,
) {
    Ok(scope) => scope,
    Err(_) => {
        crate::service::erase_json(&mut service_request.body);
        return (
            snapshot::NativeReply::Json(Response::error(
                400,
                "invalid request-owned logical data",
            )),
            is_head,
            request.namespace,
        );
    }
};
let mut reply = if let Err(response) = &consistency {
    let mut rejected = audited_wire_rejection(
        service,
        attempt_id,
        WireRejection::ParseRejected,
        response.status,
        "consistency prerequisite was not satisfied",
        execution_deadline_with_response_reserve(Instant::now(), deadline),
    );
    if rejected.status == response.status {
        rejected.body = response.body.clone();
    }
    crate::service::erase_json(&mut service_request.body);
    snapshot::NativeReply::Json(rejected)
} else if let Some(native) = native_snapshot {
    execute_deferred_native_body(service, service_request, native, source, deadline)
} else if matches!(consistency, Ok(true)) {

let path = parts.uri.path();
// HTTP/2 currently buffers DATA before logical admission. The large lane
// requires affine admission first, so refuse this unsupported transport
// before reading any DATA rather than expanding that unauthenticated cap.
if path == "/v1/sys/migration/openbao/kv2/native-large" {
    let service = Arc::clone(&context.service);
    let response = tokio::task::spawn_blocking(move || {
        audited_wire_rejection(
            &service,
            &attempt,
            WireRejection::ParseRejected,
            501,
            "native-large KV2 requires HTTP/1.1 admitted upload",
            deadline,
        )
    })
    .await
    .map_err(|_| ())?;
    return send_reply(
        sender,
        snapshot::NativeReply::Json(response),
        false,
        "",
        deadline,
    )
    .await;
}
let maximum = if matches!(
    path,
    "/v1/sys/storage/raft/snapshot" | "/v1/sys/storage/raft/snapshot-force"
) {
    MAX_SNAPSHOT_BODY
} else {
    json_ingress_body_limit(
        parts.method.as_str(),
        path.strip_prefix("/v1/").unwrap_or(""),
        parts
            .headers
            .get(::http::header::CONTENT_TYPE)
            .and_then(|value| value.to_str().ok()),
    )
};
let mut payload = Zeroizing::new(Vec::new());
while let Some(chunk) = body.data().await {
    let chunk = chunk.map_err(|_| ())?;
    if payload
        .len()
        .checked_add(chunk.len())
        .is_none_or(|size| size > maximum)
    {
        let service = Arc::clone(&context.service);
        let response = tokio::task::spawn_blocking(move || {
            audited_wire_rejection(
                &service,
                &attempt,
                WireRejection::ParseRejected,
                413,
                "request body exceeds limit",
                deadline,
            )
        })
        .await
        .map_err(|_| ())?;
        return send_reply(
            sender,
            snapshot::NativeReply::Json(response),
            false,
            "",
            deadline,
        )
        .await;
    }
    payload.extend_from_slice(&chunk);
    body.flow_control()
        .release_capacity(chunk.len())
        .map_err(|_| ())?;
}
let wire = request_wire(&parts, &payload);
let reply = tokio::task::spawn_blocking(move || {
    run_unentered_service_worker(deadline, move || {
        let (wire, rejection) = match wire {
            Ok(wire) => (wire, None),
            Err(error) => (Zeroizing::new(Vec::new()), Some(error)),
        };
        let mut source = io::Cursor::new(wire);
        let parsed = match rejection {
            Some(error) => Err(error),
            None => read_request_with_ui(
                &mut source,
                deadline.saturating_duration_since(Instant::now()),
                true,
                context.ui_assets.is_some(),
            ),
        };
        process_parsed_request(
            &context.service,
            context.ui_assets.as_deref(),
            parsed,
            &mut source,
            context.certificates.clone(),
            context.peer,
            &attempt,
            context.consistency,
            deadline,
        )
    })
})
.await
.map_err(|_| ())??;
send_reply(sender, reply.0, reply.1, &reply.2, deadline).await

pub(crate) const MAX_NATIVE_STATE: u64 = 130 * 1024 * 1024;
// Legacy HBB2 state remains bounded to 130 MiB. Only the explicit native-V6
// build accepts the separately bounded external-object pack transport.
#[cfg(feature = "native-v6-storage")]
pub(crate) const MAX_V6_SNAPSHOT_STATE: u64 =
    MAX_NATIVE_STATE + 1024 * 1024 * 1024 + 65_536 * 4 + 4132;
// HA carries both the independent local pack and shared-key typed closure.
// Keep this explicit transport bound below the 8 GiB ustar size-field limit;
// each constituent retains its own stricter validation and source limit.
#[cfg(feature = "native-v6-ha")]
pub(crate) const MAX_V6_HA_SNAPSHOT_STATE: u64 = 2 * MAX_V6_SNAPSHOT_STATE + 64 * 1024 * 1024;
#[cfg(feature = "native-v6-ha")]
pub(crate) const MAX_SNAPSHOT_ENTRY: u64 = MAX_V6_HA_SNAPSHOT_STATE;
#[cfg(all(feature = "native-v6-storage", not(feature = "native-v6-ha")))]
pub(crate) const MAX_SNAPSHOT_ENTRY: u64 = MAX_V6_SNAPSHOT_STATE;
#[cfg(not(feature = "native-v6-storage"))]
pub(crate) const MAX_SNAPSHOT_ENTRY: u64 = MAX_NATIVE_STATE;
pub(crate) const MAX_NATIVE_ARCHIVE: u64 = MAX_SNAPSHOT_ENTRY + 1024 * 1024;
#[cfg(unix)]
const DIRECTORY: &str = ".snapshot-transfer";

pub(crate) struct SnapshotSpool {
    #[cfg(unix)]
    parent: File,
    // A private held directory descriptor cannot change its device/inode.
    // This is its immutable identity, never a cached UID, mode or path result.
    #[cfg(unix)]
    parent_identity: (u64, u64),
    #[cfg(unix)]
    original: PathBuf,
    directory: ExclusiveDirectory,
    busy: AtomicBool,
}

    pub(crate) fn lease(self: &Arc<Self>) -> io::Result<Arc<SnapshotLease>> {
        self.verify()?;
        self.busy
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .map_err(|_| {
                io::Error::new(
                    io::ErrorKind::WouldBlock,
                    "snapshot transfer is already active",
                )
            })?;
        Ok(Arc::new(SnapshotLease {
            spool: Arc::clone(self),
        }))
    }
}

pub(crate) struct SnapshotLease {
    spool: Arc<SnapshotSpool>,
}
impl Drop for SnapshotLease {
    fn drop(&mut self) {
        self.spool.busy.store(false, Ordering::Release);
    }

    pub(crate) fn file(
        self: &Arc<Self>,
        maximum: u64,
        deadline: Instant,
    ) -> io::Result<SnapshotFile> {
        self.spool.verify()?;
        let nonce = crate::crypto::random::<16>().map_err(|_| invalid())?;
        let suffix: String = nonce.iter().map(|byte| format!("{byte:02x}")).collect();
        let name = format!("transfer-{suffix}");
        let file = self
            .spool
            .directory
            .open_file(&name, FileAccess::CreateNewReadWrite)?;
        // Open descriptor is the capability. Cancel, panic, reset, timeout and
        // process death all close it; there is no named uploaded state to adopt.
        if self.spool.directory.remove_file(&name).is_err() {
            drop(file);
            return Err(invalid());
        }
        self.spool.verify()?;
        Ok(SnapshotFile {
            file,
            lease: Arc::clone(self),
            maximum,
            length: 0,
            deadline,
        })
    }
}

pub(crate) struct SnapshotFile {
    file: File,
    lease: Arc<SnapshotLease>,
    maximum: u64,
    length: u64,
    deadline: Instant,
}
impl SnapshotFile {
    pub(crate) fn len(&self) -> u64 {
        self.length
    }
    pub(crate) fn rewind_checked(&mut self) -> io::Result<()> {
        self.lease.spool.verify()?;
        self.seek(SeekFrom::Start(0))?;
        Ok(())
    }
    fn check(&self) -> io::Result<()> {
        if Instant::now() >= self.deadline {
            return Err(io::Error::new(
                io::ErrorKind::TimedOut,
                "snapshot transfer deadline exceeded",
            ));
        }
        Ok(())

pub struct AuthenticatedPeerFrame {
    payload: Vec<u8>,
    peer: NodeId,
    leaf_sha256: [u8; 32],
    accepted_at: Instant,
    deadline: Instant,
    strict_raft_alpn: bool,
}

impl fmt::Debug for AuthenticatedPeerFrame {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
