}

impl AuthenticatedPeerFrame {
    pub fn payload(&self) -> &[u8] {
        &self.payload
    }
    pub fn peer(&self) -> &NodeId {
        &self.peer
    }
    pub fn actual_leaf_sha256(&self) -> [u8; 32] {
        self.leaf_sha256
    }
    pub fn accepted_at(&self) -> Instant {
        self.accepted_at
    }
    pub fn deadline(&self) -> Instant {
        self.deadline
    }
    pub fn has_strict_raft_alpn(&self) -> bool {
        self.strict_raft_alpn
    }
    /// Consuming legacy handoff preserves its previous callback contract. The
    /// resulting parts cannot reconstruct an authenticated native frame.
    pub fn into_legacy_parts(self) -> (NodeId, Vec<u8>, Instant) {
        (self.peer, self.payload, self.accepted_at)

/// Mint the opaque frame only after the actual mTLS handshake, verified leaf
/// pin and bounded frame read. The accepted socket's original absolute bound
/// covers handshake, frame, callback, reply and final flush. A legacy missing
/// ALPN exception is recorded; native receivers must explicitly reject it.
pub fn serve_one_mtls_authenticated_peer_frame<H>(
    listener: &TcpListener,
    server_config: Arc<rustls::ServerConfig>,
    identities: &PinnedClientCertificateMap,
    timeout: Duration,
    allow_missing_raft_alpn: bool,
    handler: H,
) -> Result<(), HaError>
where
    H: FnOnce(AuthenticatedPeerFrame) -> Result<Vec<u8>, HaError>,
{
    if timeout.is_zero() || timeout > Duration::from_secs(60) {
        return Err(HaError::InvalidCluster);
    }
    let (stream, accepted_at) = accept_peer_with_origin(listener)?;
    configure_accepted_peer_stream(&stream, timeout)?;
    let deadline = accepted_at.checked_add(timeout).ok_or(HaError::Transport)?;
    #[cfg(all(
        feature = "native-v6-peer-ingress",
        any(test, feature = "private-forward-stage-diagnostic")
    ))]
    let _diagnostic_bound = closure_phase_diagnostic::Scope::original_bound(deadline);
    let stream = ForwardDeadlineStream { stream, deadline };
    let connection = rustls::ServerConnection::new(server_config)
        .map_err(|_| forward_transport_frame_error("receiver_tls_setup", HaError::Transport))?;
    let mut tls = rustls::StreamOwned::new(connection, stream);
    observe_closure_phase!(ServerHandshake, tls.conn.complete_io(&mut tls.sock)).map_err(
        |error| {
            forward_io_error_as(
                "receiver_tls_handshake",
                &error,
                HaError::PeerAuthenticationFailed,
            )
        },
    )?;
    let strict_raft_alpn = tls.conn.alpn_protocol() == Some(RAFT_ALPN_PROTOCOL);
    require_raft_alpn(tls.conn.alpn_protocol(), allow_missing_raft_alpn)
        .map_err(|error| forward_transport_frame_error("receiver_alpn", error))?;
    let certificates = tls.conn.peer_certificates().ok_or_else(|| {
        forward_transport_frame_error(
            "receiver_certificate_absent",
            HaError::PeerAuthenticationFailed,
        )
    })?;
    let peer = identify_peer_certificate_chain(identities, certificates)
        .map_err(|error| forward_transport_frame_error("receiver_identity", error))?;
    let leaf_sha256 = sha256(
        certificates
            .first()
            .ok_or(HaError::PeerAuthenticationFailed)?
            .as_ref(),
    );
    let payload = native_kv2_write_request::read_authenticated_request(
        &mut tls,
        strict_raft_alpn.then_some(RAFT_ALPN_PROTOCOL),
    )
    .map_err(|error| forward_transport_frame_error("receiver_frame_read", error))?;
    let response_profile = ResponseFrameProfile::for_request(&payload)?;
    #[cfg(feature = "native-v6-peer-ingress")]
    let coalesced_root_reply = strict_raft_alpn
        && response_profile == ResponseFrameProfile::Legacy
        && is_native_v6_root_pull_frame(&payload);
    response_profile.require_alpn(tls.conn.alpn_protocol())?;
    if Instant::now() >= deadline {
        return Err(forward_transport_frame_error(
            "receiver_deadline_before_handler",
            HaError::Transport,
        ));
    }
    let response = zeroize::Zeroizing::new(
        handler(AuthenticatedPeerFrame {
            payload,
            peer,
            leaf_sha256,
            accepted_at,
            deadline,
            strict_raft_alpn,
        })
        .map_err(|error| forward_transport_frame_error("receiver_handler_result", error))?,
    );
    // Only an authenticated HBVP2 handler result uses the existing bounded
    // coalesced writer. Borrow Stream: StreamOwned's default write_vectored
    // otherwise sends only the first slice and emits a separate header record.
    // The accepted ForwardDeadlineStream still bounds every actual socket I/O.
    #[cfg(feature = "native-v6-peer-ingress")]
    if coalesced_root_reply {
        return write_coalesced_bounded_frame(
            &mut rustls::Stream::new(&mut tls.conn, &mut tls.sock),
            &response,
        )
        .map_err(|error| forward_transport_frame_error("receiver_frame_write", error));
    }
    response_profile
        .write(&mut tls, &response)
        .map_err(|error| forward_transport_frame_error("receiver_frame_write", error))
}

pub struct TlsPeerEndpoint {
    pub address: SocketAddr,
    pub server_name: String,
}

impl TlsPeerEndpoint {
    pub fn new(address: SocketAddr, server_name: impl Into<String>) -> Result<Self, HaError> {
        let server_name = server_name.into();
        if address.port() == 0
            || address.ip().is_unspecified()
            || server_name.is_empty()
            || server_name.len() > 253
            || rustls::pki_types::ServerName::try_from(server_name.clone()).is_err()
        {
            return Err(HaError::InvalidCluster);
        }
        Ok(Self {
            address,
            server_name,
        })
    }
}

#[derive(Clone)]
pub struct MutualTlsPeerTransport {
    peers: BTreeMap<NodeId, TlsPeerEndpoint>,
    client_config: Arc<rustls::ClientConfig>,
    timeout: Duration,
}

/// Private V6 ciphertext ingress: authenticate the *receiving* node's
/// exact enrolled server leaf and Raft ALPN before transmitting any
/// ciphertext bytes. The ordinary production forwarding method is
/// unchanged, and this does NOT validate Raft leadership/epoch/quorum.
///
/// The pinned hash must come from independently authenticated membership,
/// not from a peer response or a caller-supplied unauthenticated frame.
#[cfg(feature = "native-v6-peer-ingress")]
pub fn exchange_before_pinned_server(
    &self,
    peer: &NodeId,
    frame: &[u8],
    caller_deadline: Instant,
    expected_server_leaf_sha256: [u8; 32],
) -> Result<Vec<u8>, HaError> {
    if expected_server_leaf_sha256 == [0; 32] {
        return Err(HaError::PeerAuthenticationFailed);
    }
    if frame.is_empty() || frame.len() > MAX_PAYLOAD_BYTES + 4096 {
        return Err(HaError::InvalidFrame);
    }
    let deadline = caller_deadline.min(Instant::now() + self.timeout);
    #[cfg(all(
        feature = "native-v6-peer-ingress",
        any(test, feature = "private-forward-stage-diagnostic")
    ))]
    let _diagnostic_bound = closure_phase_diagnostic::Scope::original_bound(deadline);
    let endpoint = self.peers.get(peer).ok_or(HaError::UnknownPeer)?;
    let server_name = rustls::pki_types::ServerName::try_from(endpoint.server_name.clone())
        .map_err(|_| HaError::InvalidCluster)?;
    let remaining = forward_remaining(deadline).map_err(|_| HaError::Transport)?;
    let stream = observe_closure_phase!(
        ClientConnect,
        TcpStream::connect_timeout(&endpoint.address, remaining)
    )
    .map_err(|_| HaError::Transport)?;
    stream.set_nodelay(true).map_err(|_| HaError::Transport)?;
    let stream = ForwardDeadlineStream { stream, deadline };
    let connection = rustls::ClientConnection::new(self.client_config.clone(), server_name)
        .map_err(|_| HaError::Transport)?;
    let mut tls = rustls::StreamOwned::new(connection, stream);

    // Finish the authenticated TLS handshake BEFORE sending any V6 frame.
    observe_closure_phase!(ClientHandshake, tls.conn.complete_io(&mut tls.sock)).map_err(
        |error| {
            forward_io_error_as(
                "pinned_client_tls_handshake",
                &error,
                HaError::PeerAuthenticationFailed,
            )
        },
    )?;
    if tls.conn.alpn_protocol() != Some(RAFT_ALPN_PROTOCOL) {
        return Err(HaError::PeerAuthenticationFailed);
    }
    let chain = tls
        .conn
        .peer_certificates()
        .ok_or(HaError::PeerAuthenticationFailed)?;
    if chain.is_empty() || chain.len() > MAX_PEER_CERT_CHAIN {
        return Err(HaError::PeerAuthenticationFailed);
    }
    let total = chain.iter().try_fold(0_usize, |sum, cert| {
        if cert.is_empty() {
            return Err(HaError::PeerAuthenticationFailed);
        }
        sum.checked_add(cert.len())
            .filter(|count| *count <= MAX_PEER_CERT_CHAIN_BYTES)
            .ok_or(HaError::PeerAuthenticationFailed)
    })?;
    if total == 0
        || digest::digest(&digest::SHA256, chain[0].as_ref()).as_ref()
            != expected_server_leaf_sha256.as_slice()
    {
        return Err(HaError::PeerAuthenticationFailed);
    }
    forward_remaining(deadline).map_err(|_| HaError::Transport)?;
    // rustls 0.23.44 StreamOwned does not implement write_vectored. Borrow
    // Stream so the length and body reach its plaintext writer together,
    // instead of flushing a separate four-byte TLS application record.
    // The underlying ForwardDeadlineStream still bounds every syscall.
    write_coalesced_bounded_frame(
        &mut rustls::Stream::new(&mut tls.conn, &mut tls.sock),
        frame,
    )?;
    let mut response = zeroize::Zeroizing::new(read_bounded_frame(&mut tls)?);
    forward_remaining(deadline).map_err(|_| HaError::Transport)?;
    Ok(std::mem::take(&mut *response))
}

/// One absolute budget includes connect and every TLS/frame I/O. The caller
/// supplies its own forwarding or consensus RPC deadline; this transport's
/// configured timeout can shorten, but cannot extend, the remaining budget.
pub fn exchange_before(
    &self,
    peer: &NodeId,
    frame: &[u8],
    caller_deadline: Instant,
) -> Result<Vec<u8>, HaError> {
    native_kv2_write_request::validate_authenticated_request(frame)?;
    let response_profile = ResponseFrameProfile::for_request(frame)?;
    let deadline = caller_deadline.min(Instant::now() + self.timeout);
    let endpoint = self.peers.get(peer).ok_or(HaError::UnknownPeer)?;
    let server_name = rustls::pki_types::ServerName::try_from(endpoint.server_name.clone())
        .map_err(|_| HaError::InvalidCluster)?;
    let remaining = forward_remaining(deadline)
        .map_err(|error| forward_transport_io_error("deadline_before_connect", &error))?;
    let stream = TcpStream::connect_timeout(&endpoint.address, remaining)
        .map_err(|error| forward_transport_io_error("tcp_connect", &error))?;
    stream
        .set_nodelay(true)
        .map_err(|error| forward_transport_io_error("tcp_nodelay", &error))?;
    let stream = ForwardDeadlineStream { stream, deadline };
    let connection = rustls::ClientConnection::new(self.client_config.clone(), server_name)
        .map_err(|_| {
            #[cfg(feature = "private-forward-stage-diagnostic")]
            eprintln!("HBHA-PRIVATE-STAGE phase=tls_client_setup category=Transport");
            HaError::Transport
        })?;
    let mut tls = rustls::StreamOwned::new(connection, stream);
    if response_profile.is_native_index() {
        // Neither response capacity nor the separate N1 write request is
        // available through the rolling missing-ALPN exception. Complete
        // the original-budget handshake before sending Q9 or N1 bytes.
        tls.conn.complete_io(&mut tls.sock).map_err(|error| {
            forward_io_error_as(
                "native_index_client_tls_handshake",
                &error,
                HaError::PeerAuthenticationFailed,
            )
        })?;
        response_profile.require_alpn(tls.conn.alpn_protocol())?;
    }
    native_kv2_write_request::write_authenticated_request(&mut tls, frame).map_err(
        |error| {
            #[cfg(feature = "private-forward-stage-diagnostic")]
            eprintln!(
                "HBHA-PRIVATE-STAGE phase=client_frame_write_tls_state handshaking={}",
                tls.conn.is_handshaking()
            );
            forward_transport_frame_error("tls_frame_write", error)
        },
    )?;
    let mut response =
        zeroize::Zeroizing::new(response_profile.read(&mut tls).map_err(|error| {
            #[cfg(feature = "private-forward-stage-diagnostic")]
            eprintln!(
                "HBHA-PRIVATE-STAGE phase=client_frame_read_tls_state handshaking={}",
                tls.conn.is_handshaking()
            );
            forward_transport_frame_error("tls_frame_read", error)
        })?);
    // Buffered TLS plaintext must not bypass the final deadline check, and
    // a rejected late response must erase its plaintext before deallocation.
    forward_remaining(deadline)
        .map_err(|error| forward_transport_io_error("deadline_after_response", &error))?;
    Ok(std::mem::take(&mut *response))

fn identify_peer_certificate_chain(
    identities: &PinnedClientCertificateMap,
    certificates: &[rustls::pki_types::CertificateDer<'_>],
) -> Result<NodeId, HaError> {
    if certificates.is_empty() || certificates.len() > MAX_PEER_CERT_CHAIN {
        return Err(HaError::PeerAuthenticationFailed);
    }
    let total_bytes = certificates.iter().try_fold(0_usize, |total, cert| {
        if cert.is_empty() {
            return Err(HaError::PeerAuthenticationFailed);
        }
        total
            .checked_add(cert.len())
            .filter(|bytes| *bytes <= MAX_PEER_CERT_CHAIN_BYTES)
            .ok_or(HaError::PeerAuthenticationFailed)
    })?;
    if total_bytes > MAX_PEER_CERT_CHAIN_BYTES {
        return Err(HaError::PeerAuthenticationFailed);
    }
    // rustls has already authenticated the complete chain. Identity pinning
    // intentionally binds only the leaf; intermediates may rotate without
    // changing the configured node identity.
    identities.identify(certificates[0].as_ref())

    pub(in crate::service::snapshot_transfer) fn finish_native_ha_snapshot_download(
        &mut self,
        plan: &SnapshotTransferPlan,
    ) -> Response {
        let result = (|| {
            self.check_native_ha_snapshot_owner(plan)?;
            let proof = plan.native_ha_source.as_ref().ok_or_else(unavailable)?;
            proof.check_with(self, Service::check_native_installed)?;
            self.check_native_ha_snapshot_owner(plan)
        })();
        match result {
            Ok(()) => Response::ok(Value::Null),
            Err(error) => error,
        }
    }

    pub(in crate::service::snapshot_transfer) fn complete_native_ha_snapshot_delivery(
        &mut self,
        plan: &SnapshotTransferPlan,
        mut response: Response,
        fingerprint: &str,
        clock: (u64, Option<RequestClock>),
    ) -> Response {
        let exported_checkpoint: Result<_, Response> = (|| {
            self.check_native_ha_snapshot_owner(plan)?;
            Ok((plan.base, self.external_effect_generation()?))
        })();
        if response.status < 400
            && let Err(error) = &exported_checkpoint
        {
            response = Response::error(
                error.status,
                "native HA snapshot source changed before terminal audit",
            );
        }
        let (mut response, receipt) = self.audit_completed_response_with_clock_receipt(
            fingerprint,
            clock,
            response,
            || {},
            true,
        );
        if response.status >= 400 {
            return response;
        }
        let checked: Result<(), Response> = (|| {
            let exported_checkpoint = exported_checkpoint?;
            let exported = plan.native_ha_source.as_ref().ok_or_else(unavailable)?;
            if let Some(receipt) = receipt {
                // This is one observation-only successor of archive A, never
                // permission to change A's archived root/generation/provenance.
                let terminal = receipt.bind_native_snapshot(exported_checkpoint)?;
                if self.current_state_identity()? != terminal.0
                    || self.external_effect_generation()? != terminal.1
                {
                    return Err(unavailable());
                }
                self.check_native_ha_snapshot_owner_at(plan, terminal.0)?;
                let source_auth = self.state.as_ref().ok_or_else(unavailable)?.auth.clone();
                let current = self
                    .capture_native_ha_request_proof(&mut || {
                        if Instant::now() >= plan.deadline {
                            return Err(unavailable());
                        }
                        source_auth
                            .authorize_request(
                                &plan.actor,
                                &plan.namespace,
                                &plan.path,
                                if plan.is_download { "read" } else { "update" },
                                snapshot_observed_time(plan.now, plan.started.elapsed()),
                            )
                            .map_err(|error| Response::error(error.status, &error.message))
                    })?
                    .ok_or_else(unavailable)?;
                exported.check_snapshot_terminal_successor(self, &current)?;
                self.check_native_ha_snapshot_owner_at(plan, terminal.0)?;
            } else {
                if self.current_state_identity()? != exported_checkpoint.0
                    || self.external_effect_generation()? != exported_checkpoint.1
                {
                    return Err(unavailable());
                }
                exported.check_with(self, Service::check_native_installed)?;
                self.check_native_ha_snapshot_owner(plan)?;
            }
            Ok(())
        })();
        if let Err(error) = checked {
            erase_json(&mut response.body);
            response.consistency_index = None;
            let now = snapshot_observed_time(plan.now, plan.started.elapsed());
            if self
                .audit_event(
                    "native-ha-snapshot-delivery-veto",
                    fingerprint,
                    now,
                    Some(error.status),
                )
                .is_err()
            {
                self.recovery_required = true;
                self.ha_activation = None;
                return Response::error(
                    503,
                    "native HA snapshot delivery veto audit failed; recovery required",
                );
            }
            return error;
        }
        response
    }
}

    fn check_native_ha_historical_delivery(
        &self,
        plan: &SnapshotTransferPlan,
        restored: &NativeHaHistoricalReceipt,
        expected: StateIdentity,
    ) -> Result<(), Response> {
        let same_ha = match (&plan.ha, &self.ha) {
            (Some(left), Some(right)) => Arc::ptr_eq(left, right),
            _ => false,
        };
        if !same_ha
            || plan.base != restored.original_identity
            || plan.activation != restored.original_activation
            || restored.original_activation == restored.restored_activation
            || self.unseal_nonce != restored.restored_activation
            || self.current_state_identity().ok() != Some(expected)
            || self
                .state
                .as_ref()
                .is_none_or(|state| state.replay_epoch != restored.restored_epoch)
            || self
                .durable
                .as_ref()
                .is_none_or(|durable| durable.replay_epoch() != restored.restored_epoch)
            || self.audit_failed
            || self.recovery_required
            || self.barrier_key.is_none()
            || self.native_root.is_none()
            || self.record_root.is_some()
            || self.postgres_durable.is_some()
            || self.durable_profile.is_some()
            || self.openbao_wrapper_owner.is_some()
            || self.native_candidate_profile.is_some()
            || Instant::now() >= plan.deadline
        {
            return Err(unavailable());
        }
        actor_original(&restored.original_auth, plan)?;
        if self.current_snapshot_seal_identity_for_plan(plan)? != plan.seal_identity {
            return Err(unavailable());
        }
        actor_original(&restored.original_auth, plan)
    }

    pub(in crate::service::snapshot_transfer) fn complete_native_ha_historical_delivery(
        &mut self,
        plan: &SnapshotTransferPlan,
        mut response: Response,
        fingerprint: &str,
        clock: (u64, Option<RequestClock>),
    ) -> Response {
        let restored = match plan.native_ha_restored.as_ref() {
            Some(restored) => restored,
            None => return unavailable(),
        };
        let checkpoint = (restored.restored_identity, restored.restored_generation);
        if response.status < 400
            && (self.external_effect_generation().ok() != Some(checkpoint.1)
                || self
                    .check_native_ha_historical_delivery(plan, restored, checkpoint.0)
                    .is_err())
        {
            response = unavailable();
        }
        // The SAME admitted RequestClock commits before the mandatory response
        // audit. Its affine receipt may authorize only this observation-only
        // successor; it cannot manufacture another historical restore epoch.
        let (mut response, clock_receipt) = self.audit_completed_response_with_clock_receipt(
            fingerprint,
            clock,
            response,
            || {},
            true,
        );
        let checked: Result<(), Response> = (|| {
            // The epoch/root has already committed. An audit, clock or final
            // original-owner failure is an uncertain delivery, never evidence
            // that the historical restore had no effect or may be retried.
            if response.status >= 400 {
                return Err(unavailable());
            }
            if let Some(receipt) = clock_receipt {
                let terminal = receipt.bind_native_snapshot(checkpoint)?;
                if self.external_effect_generation()? != terminal.1 {
                    return Err(unavailable());
                }
                self.check_native_ha_historical_delivery(plan, restored, terminal.0)?;
                let current = self
                    .capture_native_ha_request_proof(&mut || {
                        actor_original(&restored.original_auth, plan)
                    })?
                    .ok_or_else(unavailable)?;
                restored
                    .proof
                    .check_snapshot_terminal_successor(self, &current)?;
                self.check_native_ha_historical_delivery(plan, restored, terminal.0)?;
            } else {
                if self.external_effect_generation()? != checkpoint.1 {
                    return Err(unavailable());
                }
                restored
                    .proof
                    .check_with(self, Service::check_native_installed)?;
                self.check_native_ha_historical_delivery(plan, restored, checkpoint.0)?;
            }
            Ok(())
        })();
        if let Err(error) = checked {
            erase_json(&mut response.body);
            response.consistency_index = None;
            let _ = self.audit_event(
                "native-ha-historical-restore-delivery-veto",
                fingerprint,
                snapshot_observed_time(plan.now, plan.started.elapsed()),
                Some(error.status),
            );
            self.recovery_required = true;
            self.ha_activation = None;
            self.ha_read_cache = None;
            return Response {
                status: 503,
                body: json!({"errors":["historical restore delivery requires reconciliation"],
                "recovery_required":true,"retry_allowed":false,"root_attempted":true,
                "recovery_reference":historical_recovery_reference(restored.operation_digest)}),
                unwrapped_json: None,
                response_headers: Default::default(),
                consistency_index: None,
            };
        }
        response
    }
}

    target: CheckedLocalRedirectTarget,
    binding: [u8; 32],
    ingress: [u8; 16],
}

impl LocalRedirectProfile {
    pub(super) fn validate_binding(&self, digest: [u8; 32]) -> Result<(), &'static str> {
        if self.binding != digest
            || crate::auth::current_ingress()
                .is_none_or(|ingress| ingress.attempt_id() != self.ingress)
        {
            return Err("local redirect belongs to another HTTP ingress");
        }
        Ok(())
    }

    pub(crate) fn matches_current(&self) -> bool {
        DATA.with(|slot| {
            let slot = slot.borrow();
            let Some(bound) = slot.as_ref() else {
                return false;
            };
            let Some(original) = bound.frame.local_redirect.as_ref() else {
                return false;
            };
            bound.frame.no_request_forwarding()
                && self.validate_binding(bound.digest).is_ok()
                && original.binding == self.binding
                && original.ingress == self.ingress
                && original.target.as_str() == self.target.as_str()
        })
    }

    pub(crate) fn into_target(self) -> CheckedLocalRedirectTarget {
        self.target
    }
}

impl DataFrame {
    // Go Header.Get selects the first field value and only tests nonemptiness.
    // In particular, the strings "false" and "0" both disable forwarding.
    pub(crate) fn no_request_forwarding(&self) -> bool {
        self.headers
            .get(NO_FORWARD_HEADER)
            .and_then(|values| values.first())
            .is_some_and(|value| !value.is_empty())
    }

    pub(crate) fn bind_local_redirect(
        &mut self,
        target: CheckedLocalRedirectTarget,
        request: (&str, &str, &str, &Value),
        ingress: &[u8; 16],
    ) -> Result<(), &'static str> {
        if !self.no_request_forwarding() || self.local_redirect.is_some() {
            return Err("local redirect requires the original nonempty HTTP preference");
        }
        let profile = LocalRedirectProfile {
            target,
            binding: binding(request.0, request.1, request.2, request.3)?,
            ingress: *ingress,
        };
        profile.validate_binding(profile.binding)?;
        self.local_redirect = Some(profile);
        Ok(())
    }
}
